#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# The UAT Records container on Fly.io (RP-1042, ADR 0026): the owner's one-time setup.
# Run from the repo root in Git Bash, after PR 1 of RP-1042 is merged:
#   bash scripts/records-uat-wizard.sh
# It writes nothing to the repo or .env. The UAT sealing authority's key goes only to Fly; the
# Fly deploy token goes only to GitHub's `uat` environment, piped, never shown on screen.

TOTAL_STAGES=6
REPO="Rabaed/rabaedV2.0"

# GitHub `uat` environment values (the library's set_secret/set_var write repo-level ones).
set_env_secret() {
  if gh secret set "$1" --env uat --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$1 (environment uat)")
    printf '  %s✓ set%s GitHub secret %s in environment uat\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("GitHub secret $1 in environment uat")
    warn "could not set $1 in environment uat"
  fi
}
set_env_var() {
  if gh variable set "$1" --env uat --repo "$REPO" --body "$2" >/dev/null; then
    printf '  %s✓ set%s GitHub variable %s in environment uat\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("GitHub variable $1=$2 in environment uat")
    warn "could not set $1 in environment uat"
  fi
}

banner "UAT Records container on Fly.io (RP-1042)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Fly.io account and its command line"
say "The Records container runs on Fly.io, in Frankfurt. You need an account with a card on it."
open_url "https://fly.io/app/sign-up"
step "Sign up (or sign in), and add a payment card under Billing: Fly needs one to run a machine."
note "One shared-cpu-2x machine with 2 GB, always on. Fly's pricing page shows what it costs."
step "Install flyctl. In PowerShell: iwr https://fly.io/install.ps1 -useb | iex"
note "Then open a new Git Bash window, so it finds flyctl, and run this wizard again if it is not found."
pause "Press Enter when flyctl is installed."
if ! command -v flyctl >/dev/null 2>&1; then
  warn "flyctl is not on this window's PATH. Open a new Git Bash window and run the wizard again."
  exit 1
fi
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh (GitHub CLI) is not signed in. Run: gh auth login   then run the wizard again."
  exit 1
fi
say "Signing in to Fly in your browser:"
flyctl auth login

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Create the Fly app"
say "One app, holding the one Records machine. Its name is part of its address, so keep it plain."
flyctl orgs list || true
ask FLY_ORG "Organization slug from the list above (usually: personal):"
ask FLY_RECORDS_APP "App name (for example rabaed-uat-records):"
if confirm "Create Fly app '$FLY_RECORDS_APP' in organization '$FLY_ORG'?"; then
  flyctl apps create "$FLY_RECORDS_APP" --org "$FLY_ORG" || warn "not created (does it exist already? then carry on)"
fi
set_env_var FLY_RECORDS_APP "$FLY_RECORDS_APP"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "The UAT sealing authority (a test key, Fly secret only)"
say "Every UAT record is sealed under a UAT-only test authority. Its key must never be in the repo,"
say "a PR, Jira or chat: it lives only as two Fly secrets."
ask AUTHORITY_DIR "A folder OUTSIDE the repo for its two files (for example $HOME/rabaed-uat-authority):"
[[ $AUTHORITY_DIR == "~"* ]] && AUTHORITY_DIR="$HOME${AUTHORITY_DIR:1}"
[[ "$AUTHORITY_DIR" = /* ]] || AUTHORITY_DIR="$PWD/$AUTHORITY_DIR"
# Node on Windows needs the Windows form of a Git Bash path.
NATIVE_DIR="$AUTHORITY_DIR"
command -v cygpath >/dev/null 2>&1 && NATIVE_DIR=$(cygpath -w "$AUTHORITY_DIR")
pnpm --filter @rabaed/worker exec tsx src/cli/uat-sealing-authority.ts "$NATIVE_DIR"
KEY_FILE="$AUTHORITY_DIR/uat-sealing-authority.key.pem"
CERT_FILE="$AUTHORITY_DIR/uat-sealing-authority.certificate.pem"
if [[ ! -f "$KEY_FILE" || ! -f "$CERT_FILE" ]]; then
  warn "The authority's files are not in $AUTHORITY_DIR; nothing was set. Fix the message above and run the wizard again."
  exit 1
fi
# One line each, line breaks as \n (the worker turns them back); piped in, never on screen.
oneline() { local s; s=$(<"$1"); s=${s//$'\r'/}; printf '%s' "${s//$'\n'/\\n}"; }
if confirm "Set UAT_SEALING_AUTHORITY_KEY and UAT_SEALING_AUTHORITY_CERTIFICATE on '$FLY_RECORDS_APP'?"; then
  printf 'UAT_SEALING_AUTHORITY_KEY=%s\nUAT_SEALING_AUTHORITY_CERTIFICATE=%s\n' "$(oneline "$KEY_FILE")" "$(oneline "$CERT_FILE")" \
    | flyctl secrets import --stage --app "$FLY_RECORDS_APP"
  flyctl secrets list --app "$FLY_RECORDS_APP"
fi
# The key file goes as soon as Fly holds both secrets; otherwise its path is named, to delete by hand.
if flyctl secrets list --app "$FLY_RECORDS_APP" | grep -q UAT_SEALING_AUTHORITY_KEY \
  && flyctl secrets list --app "$FLY_RECORDS_APP" | grep -q UAT_SEALING_AUTHORITY_CERTIFICATE; then
  rm -f "$KEY_FILE"
  say "Fly holds both secrets, so the key file is deleted. The certificate stays; it is public."
else
  warn "Fly does not hold both secrets yet. The private key is still at $KEY_FILE: delete it once they are set."
  SKIPPED+=("Delete the private key file $KEY_FILE once both Fly secrets are set")
fi

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Let GitHub deploy the app"
say "A deploy token for this one app, valid a year, goes straight into GitHub's uat environment."
if confirm "Create the token and store it as FLY_API_TOKEN in environment uat?"; then
  # Held only in this variable, never on screen; nothing is set when flyctl gave no token.
  token=$(flyctl tokens create deploy --app "$FLY_RECORDS_APP" --expiry 8760h) || token=""
  if [[ -n $token ]]; then
    printf '%s' "$token" | set_env_secret FLY_API_TOKEN
  else
    warn "flyctl gave no token; FLY_API_TOKEN was not set. Run this stage again."
    SKIPPED+=("GitHub secret FLY_API_TOKEN in environment uat")
  fi
  unset token
fi
note "The database, file store and web address come from the uat environment you already have."

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "First deploy"
say "The workflow 'Deploy UAT Records container' (PR 2 of RP-1042) must be on main first."
open_url "https://github.com/$REPO/actions/workflows/deploy-records-uat.yml"
if confirm "Is PR 2 merged, so the workflow is listed? Start a deploy of main now?"; then
  gh workflow run deploy-records-uat.yml --repo "$REPO" --ref main
  say "Started. It takes about 10 minutes (it builds Chromium and veraPDF into the image)."
  step "Wait for the run on the page that opened to go green."
else
  SKIPPED+=("First deploy: Actions > Deploy UAT Records container > Run workflow, once PR 2 is merged")
fi
pause "Press Enter when the run is green (or to skip)."

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Check a record on UAT"
say "On the UAT web app, close a demo item with an outcome (for example approve a MAR with Code A)."
step "Within a minute its Documental Record is ready: download it."
step "Every page shows UAT in its four corners."
step "Scan its QR (or open Verify): the page says 'Test record: not a valid record'."
note "No record after a few minutes? flyctl logs --app $FLY_RECORDS_APP   shows why (no secret is logged)."
pause "Press Enter when you've seen it."

finish
